using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record QuoteCheckoutQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode, bool Express);

public sealed record CheckoutQuote(int PayableCents, int ShippingCents, int TotalCents);

public sealed class QuoteCheckout
{
    private readonly CalculateLoyaltyDiscount discount = new();
    private readonly CalculateShippingFee shipping = new();

    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var payable = discount
            .Handle(new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode))
            .TotalCents;
        var fee = shipping.Handle(new CalculateShippingFeeQuery(payable, query.LoyaltyTier, query.Express));
        return new CheckoutQuote(payable, fee, payable + fee);
    }
}

